225	// Python modules that CPython would run (pybridge), written in plain Python and built with the program instead
226	// when the sandbox turns CPython off (no `allow native`). Each holds only what needs no file, process, network
227	// or environment access: os is os.path and its constants, pathlib is PurePath. caps.rs refuses any other use
228	// of os and pathlib before this runs. Their results match CPython's on POSIX systems.
229	// every import in the package's .py files names the package itself, a module Brevi builds in, or a file of the
230	// program next to the package
231	fn package_native(pkg: &Path, top: &str) -> bool {
232	    let Ok(rd) = std::fs::read_dir(pkg) else { return false };
233	    let parent = pkg.parent().unwrap_or(Path::new("."));
234	    for e in rd.flatten() {
235	        let p = e.path();
236	        if p.is_dir() {
237	            if p.join("__init__.py").is_file() && !package_native(&p, top) {
238	                return false;
239	            }
240	            continue;
241	        }
242	        if p.extension().and_then(|x| x.to_str()) != Some("py") {
243	            continue;
244	        }
245	        let Ok(src) = crate::read_src(&p) else { return false };
246	        for l in src.lines() {
247	            let t = l.trim_start();
248	            let names: Vec<&str> = if let Some(r) = t.strip_prefix("import ") {
249	                r.split(',').filter_map(|x| x.split_whitespace().next()).collect()
250	            } else if let Some(r) = t.strip_prefix("from ") {
251	                r.split_whitespace().next().into_iter().collect()
252	            } else {
253	                continue;
254	            };
255	            for n in names {
256	                let first = n.split('.').next().unwrap_or(n);
257	                if n.starts_with('.') || first == top || emit::builtin_mod(n) || emit::builtin_mod(first) || sandbox_module(n).is_some() || parent.join(format!("{first}.py")).is_file() {
258	                    continue;
259	                }
260	                return false;
261	            }
262	        }
263	    }
264	    true
265	}
